-- Bridge service role can preflight explicit staff mappings; member scope and existing ACL remain intact.
CREATE OR REPLACE FUNCTION public.ludia_staff_availability(p_salon_id uuid, p_staff_user_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_exclude_appointment_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare v_timezone text := 'Asia/Seoul'; v_local_start timestamp; v_local_end timestamp; v_rule public.ludia_staff_work_rules%rowtype; begin if auth.role() is distinct from 'service_role' and not public.ludia_is_salon_member(p_salon_id) then raise exception 'not authorized'; end if; if p_staff_user_id is null or p_starts_at is null or p_ends_at is null or p_ends_at<=p_starts_at then return jsonb_build_object('available',false,'reason','invalid_time'); end if; select coalesce(timezone,'Asia/Seoul') into v_timezone from public.ludia_salons where id=p_salon_id; if not exists(select 1 from public.ludia_salon_members where salon_id=p_salon_id and user_id=p_staff_user_id and is_active) then return jsonb_build_object('available',false,'reason','inactive_staff'); end if; v_local_start:=p_starts_at at time zone v_timezone; v_local_end:=p_ends_at at time zone v_timezone; if v_local_start::date<>v_local_end::date then return jsonb_build_object('available',false,'reason','outside_work_hours'); end if; select * into v_rule from public.ludia_staff_work_rules where salon_id=p_salon_id and staff_user_id=p_staff_user_id and weekday=extract(dow from v_local_start)::smallint; if found and (not v_rule.is_working or v_rule.starts_at is null or v_rule.ends_at is null or v_local_start::time<v_rule.starts_at or v_local_end::time>v_rule.ends_at) then return jsonb_build_object('available',false,'reason','outside_work_hours'); end if; if exists(select 1 from public.ludia_staff_time_off t where t.salon_id=p_salon_id and t.staff_user_id=p_staff_user_id and t.starts_at<p_ends_at and t.ends_at>p_starts_at) then return jsonb_build_object('available',false,'reason','time_off'); end if; if exists(select 1 from public.ludia_appointments a where a.salon_id=p_salon_id and a.staff_user_id=p_staff_user_id and a.status not in ('cancelled','no_show') and (p_exclude_appointment_id is null or a.id<>p_exclude_appointment_id) and a.starts_at<p_ends_at and a.ends_at>p_starts_at) then return jsonb_build_object('available',false,'reason','appointment_conflict'); end if; return jsonb_build_object('available',true,'reason',null); end $function$

